second_largest.correct_code:
def second_largest(nums):
    if len(nums) < 1:
        return None
    first = float('-inf')
    second = float('-inf')
    for num in nums:
        if num > first:
            second = first
            first = num
        elif num > second and num != first:
            second = num
    return second if second != float('-inf') else first

binary_search.correct_code:
def binary_search(arr, target):
    left = 0
    right = len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

flatten_list.correct_code:
def flatten_list(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten_list(item))
        else:
            result.append(item)
    return result

count_words.correct_code:
def count_words(text):
    counts = {}
    if not text:
        return counts
    words = text.lower().split()
    for word in words:
        if word in counts:
            counts[word] = counts[word] + 1
        else:
            counts[word] = 1
    return counts

merge_sorted.correct_code:
def merge_sorted(list1, list2):
    result = []
    i = 0
    j = 0
    while i < len(list1) and j < len(list2):
        if list1[i] <= list2[j]:
            result.append(list1[i])
            i = i + 1
        else:
            result.append(list2[j])
            j = j + 1
    while i < len(list1):
        result.append(list1[i])
        i = i + 1
    while j < len(list2):
        result.append(list2[j])
        j = j + 1
    return result

compound_discount.correct_code:
def compound_discount(price, discounts):
    result = price
    for d in discounts:
        result = result * (1 - d / 100)
    return round(result, 2)

is_palindrome.correct_code:
def is_palindrome(s):
    cleaned = ''
    for ch in s:
        if ch.isalnum():
            cleaned = cleaned + ch.lower()
    left = 0
    right = len(cleaned) - 1
    while left < right:
        if cleaned[left] != cleaned[right]:
            return False
        left = left + 1
        right = right - 1
    return True

find_duplicates.correct_code:
def find_duplicates(lst):
    seen = set()
    duplicates = set()
    for x in lst:
        if x in seen:
            duplicates.add(x)
        else:
            seen.add(x)
    return sorted(list(duplicates))

running_average.correct_code:
def running_average(nums):
    if not nums:
        return []
    result = []
    total = 0
    for i in range(len(nums)):
        total = total + nums[i]
        result.append(total / (i + 1))
    return result

validate_brackets.correct_code:
def validate_brackets(s):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    openers = set(['(', '[', '{'])
    for ch in s:
        if ch in openers:
            stack.append(ch)
        elif ch in pairs:
            if not stack:
                return False
            if stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return len(stack) == 0

caesar_cipher.correct_code:
def caesar_cipher(text, shift):
    result = ''
    for ch in text:
        if 'a' <= ch <= 'z':
            base = ord('a')
            result = result + chr((ord(ch) - base + shift) % 26 + base)
        elif 'A' <= ch <= 'Z':
            base = ord('A')
            result = result + chr((ord(ch) - base + shift) % 26 + base)
        else:
            result = result + ch
    return result

longest_common_prefix.correct_code:
def longest_common_prefix(strs):
    if not strs:
        return ''
    prefix = strs[0]
    for s in strs[1:]:
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if prefix == '':
                return ''
    return prefix

remove_duplicates_sorted.correct_code:
def remove_duplicates_sorted(arr):
    if not arr:
        return 0
    write = 1
    for i in range(1, len(arr)):
        if arr[i] != arr[i - 1]:
            arr[write] = arr[i]
            write = write + 1
    return write

moving_average.correct_code:
def moving_average(nums, window):
    if not nums or window <= 0:
        return []
    result = []
    for i in range(len(nums)):
        start = max(0, i - window + 1)
        chunk = nums[start:i + 1]
        avg = sum(chunk) / len(chunk)
        result.append(avg)
    return result
